import { Text } from '@react-three/drei'
import {
  type FontRole,
  type LuminanceLevel,
  lastResortFont,
  lazyModule,
  useLuminance,
  useMaterial,
  useNodeRenderer,
  useTextFont,
  useWorld,
  type Vec3,
} from '@runek/core'
import { Children, type ReactNode, useEffect, useMemo } from 'react'
import { Color, DoubleSide, FrontSide, type Texture } from 'three'
// @ts-expect-error troika-three-text (what drei's Text draws with) ships no types
import { configureTextBuilder } from 'troika-three-text'

// Whatever a text's font lacks, troika draws from its default font, and without one it looks the
// character up on a public CDN. Runek's box face, built in code, claims every character, so no
// text ever leaves the fonts the world declared. troika takes this once, before its first text.
// The WebGPU (TSL) twin of troika's text material, loaded only under a node renderer.
const textNodes = lazyModule(() => import('./nodes/text'))

const CONFIGURED = Symbol.for('runek.textBuilder')
const page = globalThis as { [CONFIGURED]?: boolean }
if (!page[CONFIGURED]) {
  page[CONFIGURED] = true
  configureTextBuilder({ defaultFontURL: lastResortFont() })
}

export interface SignProps {
  /** The text to render. */
  children: ReactNode
  position?: Vec3
  rotation?: Vec3
  /** Accepted for the component contract; this component has no seeded variation yet. */
  seed?: number
  /**
   * Which world font role to render in (`display` for titles/signage, `body`
   * for labels). The world declares the actual face via `<World fonts>`; an
   * undeclared role falls back to the font bundled in `@runek/core`. Text the face
   * can't fully draw is drawn in the world's `fallback` font that covers more of it;
   * characters no declared font has draw as boxes. (Named `variant`, not `role`, so it
   * doesn't trip JSX a11y linters.)
   */
  variant?: FontRole
  /** Explicit font URL, overriding the world role. The world's `fallback` fonts still apply. */
  font?: string
  /** Cap height in units. */
  size?: number
  /** Text color. Defaults to the world palette's `accent` slot. */
  color?: string
  /** Wrap width in units; omit to keep the text on one line. */
  maxWidth?: number
  letterSpacing?: number
  anchorX?: 'left' | 'center' | 'right'
  anchorY?: 'top' | 'middle' | 'bottom'
  /** Soft colored halo around the glyphs, for a glow without bloom. */
  glow?: boolean
  /** A crisp edge in this color, so the text reads against any background. Wins over `glow`. */
  outline?: string
  /** Glow: unlit by the scene and brightened by the world's `sign` luminance level, so lettering
   *  reads as light and, above 1, blooms. Name another level (`screen`, `tube`) to glow at that
   *  one instead. */
  lit?: boolean | LuminanceLevel
  /** Read from both sides, for a sign that stands free of a wall (hanging, on a roof, on a glass
   *  door): two faces back to back, each front-side only, so neither shows the other mirrored. */
  twoSided?: boolean
  /** Called with the laid-out text's width and height, in world units, whenever it changes:
   *  for fitting a backdrop behind it. */
  onBounds?: (width: number, height: number) => void
}

/**
 * In-world text. The one component that renders glyphs, and so the single
 * carve-out to the no-assets rule (CONTRACT §4): it ships no font of its own,
 * drawing only from the world's declared `fonts` or the default bundled in
 * `@runek/core`. `lit` makes it glow at a world luminance level, `twoSided` reads
 * it from behind as well. Decorative: it registers no colliders (mount it on a
 * surface that has one, e.g. a Wall).
 */
export function Sign({
  children,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  variant = 'display',
  font,
  size = 0.3,
  color,
  maxWidth,
  letterSpacing = 0,
  anchorX = 'center',
  anchorY = 'middle',
  glow = false,
  outline,
  lit = false,
  twoSided = false,
  onBounds,
}: SignProps) {
  const { unit, fonts, palette } = useWorld()
  const luminance = useLuminance()
  const face = useTextFont(font ?? fonts[variant], textOf(children))
  const ink = color ?? palette.accent
  const level = lit ? luminance[lit === true ? 'sign' : lit] : 1
  const tint = useMemo(() => (lit ? new Color(ink).multiplyScalar(level) : ink), [lit, ink, level])
  // The glyphs' base material, shared: troika keeps each text's color on its own derived copy.
  const side = twoSided ? FrontSide : DoubleSide
  const material = useMaterial({ kind: 'basic', transparent: true, side, toneMapped: !lit })
  // Under WebGPU troika's GLSL doesn't compile: each text mesh gets the node twin, its own since
  // troika keeps per-mesh values on it.
  const nodes = useNodeRenderer() ? textNodes() : null
  const faces = useMemo(
    () =>
      nodes && [
        nodes.textMaterial({ side, toneMapped: !lit }),
        nodes.textMaterial({ side, toneMapped: !lit }),
      ],
    [nodes, side, lit],
  )
  useEffect(
    () => () => {
      for (const f of faces ?? []) f.dispose()
    },
    [faces],
  )

  const text = (anchor: SignProps['anchorX'], which: number, report?: SignProps['onBounds']) => (
    <Text
      ref={settle}
      font={face}
      material={faces?.[which] ?? material}
      fontSize={size * unit}
      color={tint}
      maxWidth={maxWidth !== undefined ? maxWidth * unit : undefined}
      letterSpacing={letterSpacing}
      anchorX={anchor}
      anchorY={anchorY}
      outlineWidth={outline ? '9%' : glow ? 0.02 * unit : 0}
      outlineColor={outline ?? tint}
      outlineBlur={outline || !glow ? 0 : '45%'}
      outlineOpacity={outline || !glow ? 1 : 0.5}
      onSync={
        report || nodes
          ? (mesh: { textRenderInfo?: { blockBounds: number[]; sdfTexture?: Texture } }) => {
              // Right after troika drew any new glyphs: the only moment WebGPU can copy them.
              nodes?.captureAtlas(mesh.textRenderInfo?.sdfTexture)
              const b = mesh.textRenderInfo?.blockBounds
              if (b && report) report(b[2] - b[0], b[3] - b[1])
            }
          : undefined
      }
    >
      {children}
    </Text>
  )

  // The back face is turned half a turn, so its anchor mirrors to cover the same span.
  const back = anchorX === 'left' ? 'right' : anchorX === 'right' ? 'left' : 'center'
  return (
    <group position={position} rotation={rotation}>
      {text(anchorX, 0, onBounds)}
      {twoSided && <group rotation={[0, Math.PI, 0]}>{text(back, 1)}</group>}
    </group>
  )
}

/** The text drei's `Text` draws from `children`: its strings and numbers, joined. */
function textOf(children: ReactNode): string {
  let text = ''
  Children.forEach(children, (child) => {
    if (typeof child === 'string' || typeof child === 'number') text += child
  })
  return text
}

/** Draw no glyphs until troika has laid the text out: its glyph geometry starts with an endless
 *  instance count, which WebGL clamps and WebGPU rejects. */
function settle(mesh: { geometry?: { instanceCount: number } } | null) {
  if (mesh?.geometry && !Number.isFinite(mesh.geometry.instanceCount))
    mesh.geometry.instanceCount = 0
}

import {
  Color,
  DataTexture,
  LinearFilter,
  type Material,
  Matrix3,
  type Side,
  type Texture,
  Vector2,
  Vector4,
} from 'three'
import {
  attribute,
  clamp,
  Discard,
  Fn,
  floor,
  fwidth,
  If,
  length,
  materialColor,
  materialOpacity,
  max,
  mix,
  mod,
  positionGeometry,
  pow,
  select,
  smoothstep,
  texture,
  uniform,
  varying,
  vec2,
  vec3,
  vec4,
} from 'three/tsl'
import { MeshBasicNodeMaterial, type Node } from 'three/webgpu'
import { beforeDraw } from './uniforms'

type F = Node<'float'>
type V2 = Node<'vec2'>
type V3 = Node<'vec3'>
type V4 = Node<'vec4'>

// TSL's types take mix/clamp as float-only; they work per component on vectors too.
const mixV = <N extends Node>(a: Node, b: Node, t: Node | number) =>
  mix(a as never, b as never, t as never) as unknown as N
const clampV = <N extends Node>(x: Node, lo: Node, hi: Node) =>
  clamp(x as never, lo as never, hi as never) as unknown as N

const captured = new WeakMap<Texture, DataTexture>()

/**
 * Copy troika's glyph atlas into a texture WebGPU can read. troika draws glyph distance fields
 * into a WebGL canvas, which has nothing left to copy by the time a WebGPU frame uploads it; read
 * it back right after troika lays text out (as troika's own Safari workaround does), in the same
 * task, and sample the copy instead.
 */
export function captureAtlas(atlas: Texture | undefined) {
  const canvas = atlas?.image as HTMLCanvasElement | undefined
  if (!atlas || typeof canvas?.getContext !== 'function') return
  const gl = (canvas.getContext('webgl2') ??
    canvas.getContext('webgl')) as WebGLRenderingContext | null
  if (!gl) return
  const { width, height } = canvas
  let copy = captured.get(atlas)
  if (!copy || copy.image.width !== width || copy.image.height !== height) {
    copy?.dispose()
    // readPixels rows run bottom up, as WebGL's flipped upload of the canvas does.
    copy = new DataTexture(new Uint8Array(width * height * 4), width, height)
    copy.magFilter = LinearFilter
    copy.minFilter = LinearFilter
    captured.set(atlas, copy)
  }
  gl.readPixels(0, 0, width, height, gl.RGBA, gl.UNSIGNED_BYTE, copy.image.data as Uint8Array)
  copy.needsUpdate = true
}

/** A uniform read from `entry.value` before each object draws: troika writes its uniforms in the
 *  text mesh's `onBeforeRender`, once per draw (outline and fill alike). */
function perDraw<N extends Node>(entry: { value: unknown }): N {
  return uniform(entry.value as never).onObjectUpdate(() => entry.value as never) as unknown as N
}

/**
 * The node (TSL) twin of troika-three-text's text material, for `WebGPURenderer`: troika's glyph
 * quads, SDF atlas, edge antialiasing and stroke, drawn by a basic node material. Give each text
 * mesh its own (troika keeps per-mesh values in `uniforms`); troika takes it as already derived and
 * fills its uniforms every draw.
 */
export function textMaterial(options: { side: Side; toneMapped: boolean }) {
  const blank = new DataTexture(new Uint8Array([0, 0, 0, 0]), 1, 1)
  blank.needsUpdate = true
  const uniforms = {
    uTroikaSDFTexture: { value: blank },
    uTroikaSDFTextureSize: { value: new Vector2(1, 1) },
    uTroikaSDFGlyphSize: { value: 1 },
    uTroikaSDFExponent: { value: 1 },
    uTroikaTotalBounds: { value: new Vector4() },
    uTroikaClipRect: { value: new Vector4() },
    uTroikaEdgeOffset: { value: 0 },
    uTroikaFillOpacity: { value: 1 },
    uTroikaPositionOffset: { value: new Vector2() },
    uTroikaCurveRadius: { value: 0 },
    uTroikaBlurRadius: { value: 0 },
    uTroikaStrokeWidth: { value: 0 },
    uTroikaStrokeColor: { value: new Color() },
    uTroikaStrokeOpacity: { value: 1 },
    uTroikaOrient: { value: new Matrix3() },
    uTroikaUseGlyphColors: { value: false },
    uTroikaSDFDebug: { value: false },
  }
  const u = <N extends Node>(name: keyof typeof uniforms) => perDraw<N>(uniforms[name])
  const textureSize = u<V2>('uTroikaSDFTextureSize')
  const glyphSize = u<F>('uTroikaSDFGlyphSize')
  const exponent = u<F>('uTroikaSDFExponent')
  const clipRect = u<V4>('uTroikaClipRect')
  const edgeOffset = u<F>('uTroikaEdgeOffset')
  const fillOpacity = u<F>('uTroikaFillOpacity')
  const positionOffset = u<V2>('uTroikaPositionOffset')
  const blur = u<F>('uTroikaBlurRadius')
  const strokeWidth = u<F>('uTroikaStrokeWidth')
  const strokeColor = u<V3>('uTroikaStrokeColor')
  const strokeOpacity = u<F>('uTroikaStrokeOpacity')
  const orient = u<Node<'mat3'>>('uTroikaOrient')

  // Vertex: stretch the unit quad over this glyph's bounds (clipped), as troika does.
  const raw = attribute('aTroikaGlyphBounds', 'vec4') as V4
  const index = attribute('aTroikaGlyphIndex', 'float') as F
  const bounds = vec4(
    raw.x.add(positionOffset.x),
    raw.y.sub(positionOffset.y),
    raw.z.add(positionOffset.x),
    raw.w.sub(positionOffset.y),
  )
  const outline = vec4(bounds.xy.sub(edgeOffset).sub(blur), bounds.zw.add(edgeOffset).add(blur))
  const lo = clampV<V2>(outline.xy, clipRect.xy, clipRect.zw)
  const hi = clampV<V2>(outline.zw, clipRect.xy, clipRect.zw)
  const glyphUV = mixV<V2>(lo, hi, positionGeometry.xy)
    .sub(bounds.xy)
    .div(bounds.zw.sub(bounds.xy)) as V2
  const placed = vec3(mixV<V2>(bounds.xy, bounds.zw, glyphUV), positionGeometry.z)
  const columns = textureSize.x.div(glyphSize)
  const square = vec2(glyphSize).div(textureSize) as V2
  const cell = floor(index.div(4))
  const start = square.mul(vec2(mod(cell, columns), floor(cell.div(columns)))) as V2

  const vGlyphUV = varying(glyphUV) as V2
  const vDims = varying(bounds.zw.sub(bounds.xy)) as V2
  const vUVBounds = varying(vec4(start, start.add(square))) as V4
  const vChannel = varying(mod(index, 4)) as F

  // Fragment: decode the glyph's signed distance and antialias its edge.
  const shade = Fn(() => {
    const aaDist = length(fwidth(vGlyphUV.mul(vDims))).mul(0.5) as F
    const edgeUV = glyphSize.reciprocal().mul(0.5)
    const clamped = clampV<V2>(vGlyphUV, vec2(edgeUV), vec2(edgeUV.oneMinus()))
    const atlas = texture(blank, mixV<V2>(vUVBounds.xy, vUVBounds.zw, clamped))
    const rgba = atlas as unknown as V4
    // Before each draw, sample the WebGPU copy of whichever atlas troika gave this mesh.
    const swap = beforeDraw(() => {
      atlas.value = captured.get(uniforms.uTroikaSDFTexture.value) ?? blank
    })
    const ch = floor(vChannel.add(0.5).add(swap))
    const alpha = select(
      ch.equal(0),
      rgba.r,
      select(ch.equal(1), rgba.g, select(ch.equal(2), rgba.b, rgba.a)),
    ) as F
    const near = select(alpha.greaterThan(0.5), alpha.oneMinus(), alpha) as F
    const maxDim = max(vDims.x, vDims.y)
    const absDist = pow(near.mul(2), exponent.reciprocal()).oneMinus().mul(maxDim)
    const signed = select(alpha.greaterThan(0.5), absDist.negate(), absDist) as F
    // Outside the glyph's square, extrapolate the distance.
    const distance = signed.add(length(vGlyphUV.sub(clamped).mul(vDims))) as F
    const aa = max(aaDist, blur)
    const edgeAlpha = smoothstep(edgeOffset.add(aa), edgeOffset.sub(aa), distance)
    If(edgeAlpha.lessThanEqual(0), () => {
      Discard()
    })
    const opacity = (materialOpacity as unknown as F).mul(fillOpacity)
    const fill = vec4(materialColor as unknown as V3, opacity) as V4
    const stroke = select(strokeWidth.equal(0), fill, vec4(strokeColor, strokeOpacity)) as V4
    const mixed = mixV<V4>(
      fill,
      stroke,
      smoothstep(strokeWidth.negate().sub(aaDist), strokeWidth.negate().add(aaDist), distance),
    )
    return vec4(mixed.rgb, mixed.a.mul(edgeAlpha))
  })

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: options.side,
    toneMapped: options.toneMapped,
  })
  material.positionNode = orient.mul(placed)
  material.colorNode = shade()
  material.forceSinglePass = true
  // What troika looks for to use a material as is rather than deriving its GLSL one from it.
  Object.assign(material, {
    uniforms,
    isTroikaTextMaterial: true,
    baseMaterial: material,
    isDerivedFrom: () => true,
  })
  return material as Material
}

import { float, uniform } from 'three/tsl'
import { Node, type NodeFrame, NodeUpdateType } from 'three/webgpu'

/** A TSL uniform that follows `entry.value` every render, so the `{ value }` records a
 *  component already updates (for its GLSL material) drive its node material too. */
export function follow<N extends Node>(entry: { value: unknown }): N {
  return uniform(entry.value as never).onRenderUpdate(() => entry.value as never) as unknown as N
}

class BeforeDraw extends Node {
  constructor(private readonly run: (frame: NodeFrame) => void) {
    super('float')
    this.updateBeforeType = NodeUpdateType.OBJECT
  }

  updateBefore(frame: NodeFrame) {
    this.run(frame)
    return true
  }

  setup() {
    return float(0)
  }
}

/**
 * A node worth 0 that runs `run` before each object using it draws: add it to anything in the
 * material to have it run. For what a uniform can't do per object, like pointing a texture node at
 * another texture (a texture node resets its own update hook when it builds).
 */
export function beforeDraw(run: (frame: NodeFrame) => void): Node<'float'> {
  return new BeforeDraw(run) as unknown as Node<'float'>
}
